# Lecture 4, parts 7-8: a full profitability analysis of תעשיות נירוסטה (the company of lectures 2-3), four lenses on one company,
# the limits of the ratios, the summary, and seven self-practice exercises.

# ================================================================ part 7: a full profitability analysis
opener(7, 'ניתוח רווחיות מלא', 'שאלת החלק: תעשיות נירוסטה הקימה קו ייצור בהלוואות. מה קרה לרווחיות, ומה אומרות ארבע ההרצאות יחד?',
       ['מסבירים יחד: נירוסטה, 2025 מול 2026', 'שלוש שאלות על הטבלה, מהקלה לקשה', 'ארבע עדשות על חברה אחת', 'מהעולם: רמי לוי במספרים אמיתיים, ומול שופרסל', 'מה יחסי הרווחיות אינם רואים', 'ארגז הכלים, ומה למדנו'], 40)

_FP = {'A1': 'תעשיות נירוסטה, אלפי ש״ח', 'B1': 'שנת 2026', 'C1': 'שנת 2025', 'D1': 'ענף', 'A2': 'מכירות', 'A3': 'עלות המכר', 'A4': 'רווח תפעולי', 'A5': 'פחת והפחתות', 'A6': 'הוצאות מימון', 'A7': 'מסים על ההכנסה',
       'A8': 'שיעור רווח גולמי', 'A9': 'שיעור רווח תפעולי', 'A10': 'שיעור EBITDA', 'A11': 'שיעור רווח נקי'}
_fpf = lambda c: {f'{c}8': f'=({c}2-{c}3)/{c}2', f'{c}9': f'={c}4/{c}2', f'{c}10': f'=({c}4+{c}5)/{c}2', f'{c}11': f'=({c}4-{c}6-{c}7)/{c}2'}
_FPS = {**_fpf('B'), **_fpf('C')}
QX('x-fs4', 'מסבירים יחד', 'תעשיות נירוסטה: הרווחיות, 2025 מול 2026',
   ['תעשיות נירוסטה בע״מ מייצרת ציוד למטבחים מוסדיים. בשנת 2026 הקימה קו ייצור חדש, ומימנה אותו בהלוואות. בגיליון: נתונים מדוחות רווח והפסד, באלפי ש״ח, והממוצע הענפי של השיעורים.',
    '<b>נדרש:</b> חשבו לכל שנה את שיעור הרווח הגולמי, התפעולי, ה-EBITDA והנקי, והשוו לענף.'],
   'מלאו את שורות 8 עד 11 בעמודה B, וגררו לעמודה C.',
   _FP, _FPS, [216, 88, 88, 62], [1],
   given={'B2': 4380, 'C2': 4380, 'B3': 2920, 'C3': 2920, 'B4': 420, 'C4': 418, 'B5': 175, 'C5': 150, 'B6': 98, 'C6': 68, 'B7': 74, 'C7': 81, 'D8': 0.35, 'D9': 0.11, 'D10': 0.14, 'D11': 0.07},
   fmt={**{f'{c}{r}': 'num0' for c in 'BC' for r in range(2, 8)}, **{f'{c}{r}': 'pct1' for c in 'BCD' for r in range(8, 12)}}, sty={**_HD('ABCD'), 'A11': {'b': True}},
   hints=['גולמי: =(B2-B3)/B2. תפעולי: =B4/B2.', 'EBITDA: =(B4+B5)/B2. נקי: =(B4-B6-B7)/B2. גוררים לעמודה C.'], remind='=(B4+B5)/B2', partial=['B8'],
   traps={'B10': [('=(B4-B5)/B2', 'ב-EBITDA מוסיפים את הפחת בחזרה: =(B4+B5)/B2.')]},
   steps=[dict(cells={f'{c}{r}': _FPS[f'{c}{r}']}, note=f'{_FP["A" + str(r)]}, {"שנת 2026" if c == "B" else "שנת 2025"}.') for r in (8, 9, 10, 11) for c in 'BC'],
   qmc=RLIST([('שיעור רווח גולמי', 'מכירות פחות עלות המכר', 'מכירות'), ('שיעור רווח תפעולי', 'רווח תפעולי', 'מכירות'), ('שיעור EBITDA', 'רווח תפעולי ועוד פחת', 'מכירות'), ('שיעור רווח נקי', 'רווח תפעולי פחות מימון ומס', 'מכירות')]),
   note=[('ans', '2026: 33.3%, 9.6%, 13.6%, 5.7%. 2025: 33.3%, 9.5%, 13.0%, 6.1%.', 1)],
   done='2026: 33.3%, 9.6%, 13.6%, 5.7%. 2025: 33.3%, 9.5%, 13.0%, 6.1%.', xtitle='תעשיות נירוסטה: רווחיות')

_fr = lambda a, b, c, d, cls='': f'<tr{" class=" + cls if cls else ""}><td>{TX(a)}</td><td class="amt">{TX(b)}</td><td class="amt">{TX(c)}</td><td class="amt">{TX(d)}</td></tr>'
_FT4 = ('<div class="card"><table class="tbl2 cen"><tr><th>' + TX('תעשיות נירוסטה') + '</th><th>2026</th><th>2025</th><th>' + TX('ענף') + '</th></tr>'
        + _fr('שיעור רווח גולמי', '33.3%', '33.3%', '35%') + _fr('שיעור רווח תפעולי', '9.6%', '9.5%', '11%') + _fr('שיעור EBITDA', '13.6%', '13.0%', '14%', 'hl') + _fr('שיעור רווח נקי', '5.7%', '6.1%', '7%', 'hl')
        + _fr('פחת והפחתות', '175', '150', '') + _fr('הוצאות מימון', '98', '68', '') + '</table></div>')
MC1('m-f4a', 'שאלה 1 על הטבלה: מה זז', 'איזה שיעור השתנה בצורה המשמעותית ביותר בין 2025 ל-2026?',
    ['שיעור הרווח הנקי: ירד מ-6.1% ל-5.7%', 'שיעור הרווח הגולמי: ירד בחדות', 'שיעור הרווח התפעולי: קפץ', 'אף שיעור לא השתנה'], 0,
    'הגולמי לא זז, והתפעולי כמעט לא. השינוי נמצא מתחת לרווח התפעולי: בשורה התחתונה. שם צריך לחפש את ההסבר.', side=_FT4)
MC1('m-f4b', 'שאלה 2 על הטבלה: EBITDA מול נקי', 'שיעור ה-EBITDA עלה, ושיעור הרווח הנקי ירד. מה מסביר את הפער?',
    ['הקו החדש הוסיף פחת, שמוחזר ב-EBITDA, וריבית על ההלוואות שמימנו אותו, שיורדת לפני הרווח הנקי', 'עלות המכר עלתה', 'החברה שילמה יותר מס', 'המכירות ירדו'], 0,
    'הפחת עלה מ-150 ל-175: ה-EBITDA מוסיף אותו בחזרה, ולכן הוא עלה. הוצאות המימון עלו מ-68 ל-98, ופגעו ברווח הנקי. והמכירות לא גדלו: הקו החדש עוד לא הניב. ה-EBITDA ״לא רואה״ לא את עלות המכונה ולא את עלות הכסף שמימן אותה.', side=_FT4)
MC1('m-f4c', 'שאלה 3 על הטבלה: המסקנה', 'איזו מסקנה מנומקת היטב מתוך הנתונים?*',
    ['הרווחיות התפעולית יציבה אך נמוכה מהענף, והרווח הנקי נשחק בגלל עלות המימון של הקו החדש. השאלה היא אם הקו יגדיל את המכירות', 'הרווחיות השתפרה, כי שיעור ה-EBITDA עלה', 'החברה מפסידה כסף', 'ההשקעה בקו החדש נכשלה'], 0,
    'הגולמי והתפעולי יציבים, שניהם מתחת לענף. הנקי ירד בגלל הריבית. ה-EBITDA אינו ראיה לשיפור, כי הוא מתעלם מהפחת ומהריבית של אותה השקעה. וקביעה שההשקעה נכשלה מוקדמת: הקו פעל חלק מהשנה.', side=_FT4, foot=_FOOT)

_lens = lambda n, ic, h, t, k: POP(n, f'<div class="ln-i">{ic}</div><b>{TX(h)}</b><p>{TX(t)}</p>', 'lcard ' + k)
S('s-lens4', 'ארבע עדשות', 'תעשיות נירוסטה: ארבע הרצאות, חברה אחת',
  '<div class="learn lens4">'
  + _lens(1, '💧', 'נזילות, הרצאה 1', 'היחס השוטף עלה מ-1.50 ל-2.00, אבל המזומן ירד מ-140 ל-20.', '')
  + _lens(2, '🏛️', 'איתנות, הרצאה 2', 'יחס ההתחייבויות להון עלה מ-0.90 ל-1.08, וכיסוי הריבית ירד מ-6.15 ל-4.29.', '')
  + _lens(3, '⚙️', 'יעילות, הרצאה 3', 'מחזור המרת המזומן התארך מ-51 ל-74 ימים, ומחזור הנכסים ירד.', '')
  + _lens(4, '📈', 'רווחיות, היום', 'הרווחיות התפעולית יציבה ונמוכה מהענף, והנקי ירד מ-6.1% ל-5.7%.', '')
  + '</div>' + BAND('ans', 'הסיפור המלא: החברה לוותה, בנתה קו, ומילאה את המחסנים. בינתיים המכירות לא זזו. כל עדשה רואה חלק; רק יחד הן מספרות מה קרה.', 5)
  + BAND('dg', 'זה המבנה של שאלת ניתוח בבחינה: מחשבים את היחסים של כל קבוצה, ואז כותבים מסקנה אחת שמחברת ביניהן.', 6), kick='חלק 7 · מהמספרים למסקנה')

_RL = {'A1': 'רמי לוי, מיליוני ש״ח', 'B1': 'שנת 2025', 'C1': 'שנת 2024', 'A2': 'הכנסות', 'A3': 'עלות המכירות', 'A4': 'רווח תפעולי', 'A5': 'רווח נקי', 'A6': 'EBITDA כפי שדווח',
       'A8': 'שיעור רווח גולמי', 'A9': 'שיעור רווח תפעולי', 'A10': 'שיעור רווח נקי', 'A11': 'שיעור EBITDA'}
_rlf = lambda c: {f'{c}8': f'=({c}2-{c}3)/{c}2', f'{c}9': f'={c}4/{c}2', f'{c}10': f'={c}5/{c}2', f'{c}11': f'={c}6/{c}2'}
