  + POP(5, '<div class="ln-i">📐</div><b>' + TX('אחוזים מסתירים היקף') + '</b><p>' + TX('שיעור גבוה על מכירות קטנות יכול להיות פחות רווח בשקלים.') + '</p><p class="ex"><b>דוגמה:</b> ' + TX('קפה הגבעה: 20% מ-400 הם פחות מ-10% מ-1,000.') + '</p>', 'lcard')
